17	/**
18	 * This page is the entry page into the quiz UI. Displays information about the
19	 * quiz to students and teachers, and lets students see their previous attempts.
20	 *
21	 * @package   mod_quiz
22	 * @copyright 1999 onwards Martin Dougiamas  {@link http://moodle.com}
23	 * @license   http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
24	 */
25	
26	use core\output\notification;
27	use mod_quiz\access_manager;
28	use mod_quiz\output\list_of_attempts;
29	use mod_quiz\output\renderer;
30	use mod_quiz\output\view_page;
31	use mod_quiz\quiz_attempt;
32	use mod_quiz\quiz_settings;
33	
34	require_once(__DIR__ . '/../../config.php');
35	require_once($CFG->libdir.'/gradelib.php');
36	require_once($CFG->dirroot.'/mod/quiz/locallib.php');
37	require_once($CFG->libdir . '/completionlib.php');
38	require_once($CFG->dirroot . '/course/format/lib.php');
39	
40	$id = optional_param('id', 0, PARAM_INT); // Course Module ID, or ...
41	$q = optional_param('q',  0, PARAM_INT);  // Quiz ID.
42	$preloginuserid = $USER->id;
43	
44	if ($id) {
45	    $quizobj = quiz_settings::create_for_cmid($id, $USER->id);
46	} else {
47	    $quizobj = quiz_settings::create($q, $USER->id);
48	}
49	$quiz = $quizobj->get_quiz();
50	$cm = $quizobj->get_cm();
51	$course = $quizobj->get_course();
52	
53	// Check login and get context.
54	require_login($course, false, $cm);
55	$context = $quizobj->get_context();
56	require_capability('mod/quiz:view', $context);
57	
58	// Apply overrides.
59	if ($USER->id !== $preloginuserid) {
60	    $quiz = quiz_update_effective_access($quiz, $USER->id);
61	}
62	// Cache some other capabilities we use several times.
63	$canattempt = has_capability('mod/quiz:attempt', $context);
64	$canreviewmine = has_capability('mod/quiz:reviewmyattempts', $context);
65	$canpreview = has_capability('mod/quiz:preview', $context);
66	
67	// Create an object to manage all the other (non-roles) access rules.
68	$timenow = time();
69	$accessmanager = new access_manager($quizobj, $timenow,
70	        has_capability('mod/quiz:ignoretimelimits', $context, null, false));
71	
72	// Trigger course_module_viewed event and completion.
73	quiz_view($quiz, $course, $cm, $context);
74	
75	// Initialize $PAGE, compute blocks.
76	$PAGE->set_url('/mod/quiz/view.php', ['id' => $cm->id]);
77	// On the quiz view page, the browser back/forwards buttons should force a reload.
78	$PAGE->set_cacheable(false);
79	
80	// Create view object which collects all the information the renderer will need.
81	$viewobj = new view_page();
82	$viewobj->accessmanager = $accessmanager;
83	$viewobj->canreviewmine = $canreviewmine || $canpreview;
84	
85	// Get this user's attempts.
86	$attempts = quiz_get_user_attempts($quiz->id, $USER->id, 'finished', true);
87	$firstfinishedattempt = reset($attempts);
88	$lastfinishedattempt = end($attempts);
89	$unfinished = false;
90	$unfinishedattemptid = null;
91	if ($unfinishedattempt = quiz_get_user_attempt_unfinished($quiz->id, $USER->id)) {
92	    $attempts[] = $unfinishedattempt;
93	
94	    // If the attempt is now overdue, deal with that - and pass isonline = false.
95	    // We want the student notified in this case.
96	    $quizobj->create_attempt_object($unfinishedattempt)->handle_if_time_expired(time(), false);
97	
98	    $unfinished = $unfinishedattempt->state == quiz_attempt::IN_PROGRESS ||
99	            $unfinishedattempt->state == quiz_attempt::OVERDUE;
100	    if (!$unfinished) {
101	        $lastfinishedattempt = $unfinishedattempt;
102	    }
103	    $unfinishedattemptid = $unfinishedattempt->id;
104	    $unfinishedattempt = null; // To make it clear we do not use this again.
105	}
106	$numattempts = count($attempts);
107	
108	$gradeitemmarks = $quizobj->get_grade_calculator()->compute_grade_item_totals_for_attempts(
109	    array_column($attempts, 'uniqueid'));
110	
111	$viewobj->attempts = $attempts;
112	$viewobj->attemptobjs = [];
113	foreach ($attempts as $attempt) {
114	    $attemptobj = new quiz_attempt($attempt, $quiz, $cm, $course, false);
115	    $attemptobj->set_grade_item_totals($gradeitemmarks[$attempt->uniqueid]);
116	    $viewobj->attemptobjs[] = $attemptobj;
117	
118	}
119	$viewobj->attemptslist = new list_of_attempts($timenow);
120	foreach (array_reverse($viewobj->attemptobjs) as $attemptobj) {
121	    $viewobj->attemptslist->add_attempt($attemptobj);
122	}
123	
124	// Work out the final grade, checking whether it was overridden in the gradebook.
125	// First, get an initial grade to display.
126	if (!$canpreview) {
127	    $mygrade = quiz_get_best_grade($quiz, $USER->id);
128	} else if ($lastfinishedattempt) {
129	    // Users who can preview the quiz don't get a proper grade, so work out a
130	    // plausible value to display instead, so the page looks right.
131	    $mygrade = quiz_rescale_grade($lastfinishedattempt->sumgrades, $quiz, false);
132	} else {
133	    $mygrade = null;
134	}
135	
136	// Now, check the grade in the gradebook, if there is one.
137	$mygradeoverridden = false;
138	$gradebookfeedback = '';
139	
140	$gradeitem = grade_item::fetch([
141	    'itemtype' => 'mod',
142	    'itemmodule' => 'quiz',
143	    'iteminstance' => $quiz->id,
144	    'itemnumber' => 0,
145	    'courseid' => $course->id,
146	]);
147	
148	// If there's a grade item grade, then get that grade for this user.
149	// Users who can preview the quiz (eg teachers) won't have a proper grade,
150	// so no point getting their grades here.
151	if (!$canpreview && $gradeitem) {
152	    $grade = $gradeitem->get_grade($USER->id, false);
153	    $mygrade = $grade->finalgrade; // Use this grade to display in the view page.
154	
155	    if ($grade->overridden) {
156	        if ($gradeitem->needsupdate) {
157	            // It is Error, but let's be consistent with the old code.
158	            $mygrade = 0;
159	        }
160	        $mygradeoverridden = true;
161	    }
162	
163	    if (!empty($grade->feedback)) {
164	        $gradebookfeedback = $grade->feedback;
165	    }
166	}
167	
168	$title = $course->shortname . ': ' . format_string($quiz->name);
169	$PAGE->set_title($title);
170	$PAGE->set_heading($course->fullname);
171	if (html_is_blank($quiz->intro)) {
172	    $PAGE->activityheader->set_description('');
173	}
174	$PAGE->add_body_class('limitedwidth');
175	/** @var renderer $output */
176	$output = $PAGE->get_renderer('mod_quiz');
177	
178	// Print overall stats and table with existing attempts.
179	if ($attempts) {
180	    // Work out which columns we need, taking account what data is available in each attempt.
181	    list($someoptions, $alloptions) = quiz_get_combined_reviewoptions($quiz, $attempts);
182	
183	    $viewobj->attemptcolumn  = $quiz->attempts != 1;
184	
185	    $viewobj->gradecolumn    = $someoptions->marks >= question_display_options::MARK_AND_MAX &&
186	            quiz_has_grades($quiz);
187	    $viewobj->markcolumn     = $viewobj->gradecolumn && ($quiz->grade != $quiz->sumgrades);
188	    $viewobj->overallstats   = $lastfinishedattempt && $alloptions->marks >= question_display_options::MARK_AND_MAX;
189	
190	    $viewobj->feedbackcolumn = quiz_has_feedback($quiz) && $alloptions->overallfeedback;
191	}
192	
193	$viewobj->timenow = $timenow;
194	$viewobj->numattempts = $numattempts;
195	$viewobj->mygrade = $mygrade;
196	$viewobj->moreattempts = $unfinished ||
197	        !$accessmanager->is_finished($numattempts, $lastfinishedattempt);
198	$viewobj->mygradeoverridden = $mygradeoverridden;
199	$viewobj->gradebookfeedback = $gradebookfeedback;
200	$viewobj->lastfinishedattempt = $lastfinishedattempt;
201	$viewobj->canedit = has_capability('mod/quiz:manage', $context);
202	$viewobj->editurl = new moodle_url('/mod/quiz/edit.php', ['cmid' => $cm->id]);
203	$viewobj->backtocourseurl = new moodle_url('/course/view.php', ['id' => $course->id]);
204	$viewobj->startattempturl = $quizobj->start_attempt_url();
205	
206	if ($accessmanager->is_preflight_check_required($unfinishedattemptid)) {
207	    $viewobj->preflightcheckform = $accessmanager->get_preflight_check_form(
208	            $viewobj->startattempturl, $unfinishedattemptid);
209	}
210	$viewobj->popuprequired = $accessmanager->attempt_must_be_in_popup();
211	$viewobj->popupoptions = $accessmanager->get_popup_options();
212	
213	// Display information about this quiz.
214	$viewobj->infomessages = $viewobj->accessmanager->describe_rules();
215	if ($quiz->attempts != 1) {
216	    $viewobj->infomessages[] = get_string('gradingmethod', 'quiz',
217	            quiz_get_grading_option_name($quiz->grademethod));
218	}
219	
220	// Quiz due status relies on the first finished attempt.
221	if ($quiz->duedate > 0) {
222	    if (empty($firstfinishedattempt) || empty($firstfinishedattempt->timefinish)) {
223	        $time = \core\di::get(\core\clock::class)->time();
224	        $duestatus = $quiz->duedate - $time <= 0
225	            ? get_string('quizoverdue', 'mod_quiz')
226	            : get_string('quizduein', 'mod_quiz', format_time($quiz->duedate - $time));
227	    } else {
228	        $timefinished = $firstfinishedattempt->timefinish;
229	        $duestatus = $quiz->duedate - $timefinished <= 0
230	            ? get_string('quizfinishedlate', 'mod_quiz', format_time($quiz->duedate - $timefinished))
231	            : get_string('quizfinishedearly', 'mod_quiz', format_time($quiz->duedate - $timefinished));
232	    }
233	    array_unshift($viewobj->infomessages, $duestatus);
234	}
235	
236	// Inform user of the grade to pass if non-zero.
237	if ($gradeitem && grade_floats_different($gradeitem->gradepass, 0)) {
238	    $a = new stdClass();
239	    $a->grade = quiz_format_grade($quiz, $gradeitem->gradepass);
240	    $a->maxgrade = quiz_format_grade($quiz, $quiz->grade);
241	    $viewobj->infomessages[] = get_string('gradetopassoutof', 'quiz', $a);
242	}
243	
244	// Determine whether a start attempt button should be displayed.
245	$viewobj->quizhasquestions = $quizobj->has_questions();
246	$viewobj->preventmessages = [];
247	if (!$viewobj->quizhasquestions) {
248	    $viewobj->buttontext = '';
249	
250	} else {
251	    if ($unfinished) {
252	        if ($canpreview) {
253	            $viewobj->buttontext = get_string('continuepreview', 'quiz');
254	        } else if ($canattempt) {
255	            $viewobj->buttontext = get_string('continueattemptquiz', 'quiz');
256	        }
257	    } else {
258	        if ($canpreview) {
259	            $viewobj->buttontext = get_string('previewquizstart', 'quiz');
260	        } else if ($canattempt) {
261	            $viewobj->preventmessages = $viewobj->accessmanager->prevent_new_attempt(
262	                    $viewobj->numattempts, $viewobj->lastfinishedattempt);
263	            if ($viewobj->preventmessages) {
264	                $viewobj->buttontext = '';
265	            } else if ($viewobj->numattempts == 0) {
266	                $viewobj->buttontext = get_string('attemptquiz', 'quiz');
267	            } else {
268	                $viewobj->buttontext = get_string('reattemptquiz', 'quiz');
269	            }
270	        }
271	    }
272	
273	    // Users who can preview the quiz should be able to see all messages for not being able to access the quiz.
274	    if ($canpreview) {
275	        $viewobj->preventmessages = $viewobj->accessmanager->prevent_access();
276	    } else if ($viewobj->buttontext) {
277	        // If, so far, we think a button should be printed, so check if they will be allowed to access it.
278	        if (!$viewobj->moreattempts) {
279	            $viewobj->buttontext = '';
280	        } else if ($canattempt) {
281	            $viewobj->preventmessages = $viewobj->accessmanager->prevent_access();
282	            if ($viewobj->preventmessages) {
283	                $viewobj->buttontext = '';
284	            }
285	        }
286	    }
287	
288	    // If the quiz has any invalid questions, we cannot attempt it.
289	    if (in_array('missingtype', $quizobj->get_all_question_types_used())) {
290	        $viewobj->preventmessages[] = $OUTPUT->notification(
291	            get_string('quizinvalidquestions', 'mod_quiz'), notification::NOTIFY_ERROR, false);
292	        $viewobj->buttontext = '';
293	    }
294	}
295	
296	$viewobj->showbacktocourse = ($viewobj->buttontext === '' &&
297	        course_get_format($course)->has_view_page());
298	
299	echo $OUTPUT->header();
300	
301	if (!empty($gradinginfo->errors)) {
302	    foreach ($gradinginfo->errors as $error) {
303	        $errortext = new notification($error, notification::NOTIFY_ERROR);
304	        echo $OUTPUT->render($errortext);
305	    }
306	}
307	
308	if (isguestuser()) {
309	    // Guests can't do a quiz, so offer them a choice of logging in or going back.
310	    echo $output->view_page_guest($course, $quiz, $cm, $context, $viewobj->infomessages, $viewobj);
311	} else if (!isguestuser() && !($canattempt || $canpreview
312	          || $viewobj->canreviewmine)) {
313	    // If they are not enrolled in this course in a good enough role, tell them to enrol.
314	    echo $output->view_page_notenrolled($course, $quiz, $cm, $context, $viewobj->infomessages, $viewobj);
315	} else {
316	    echo $output->view_page($course, $quiz, $cm, $context, $viewobj);
317	}
318	
319	echo $OUTPUT->footer();
320

